pub async fn connect_git_repo(args_json: String) -> Result<String, CoreError> {
    run_blocking(move || {
        let args: ConnectGitArgs = from_json(&args_json)?;
        to_json(&git_sync_use_cases()?.connect(args)?)
    })
    .await
}

