  connect: (args: ConnectGitArgs) => Promise<void>;
  /** Persist a scanned sync link to the working folder's settings + connect. */
  connectFromLink: (link: SyncDeepLinkParams) => Promise<void>;
  pull: () => Promise<void>;
  push: (message?: string) => Promise<void>;
