   575	/// Browse the local network for advertised sync servers for up to `timeout_ms`.
   576	pub fn discover_local_sync_servers_impl(timeout_ms: u64) -> Result<Vec<DiscoveredServer>, String> {
   577	    let timeout_ms = timeout_ms.clamp(500, 10_000);
   578	    let mdns = ServiceDaemon::new().map_err(|e| format!("mDNS init failed: {e}"))?;
   579	    let receiver = mdns
   580	        .browse(MDNS_SERVICE_TYPE)
   581	        .map_err(|e| format!("mDNS browse failed: {e}"))?;
   582	
   583	    let deadline = Instant::now() + Duration::from_millis(timeout_ms);
   584	    let mut found: HashMap<String, DiscoveredServer> = HashMap::new();
   585	    loop {
   586	        let remaining = deadline.saturating_duration_since(Instant::now());
   587	        if remaining.is_zero() {
   588	            break;
   589	        }
   590	        match receiver.recv_timeout(remaining) {
   591	            Ok(ServiceEvent::ServiceResolved(info)) => {
   592	                if let Some(server) = discovered_from_info(&info) {
   593	                    found.insert(info.fullname.clone(), server);
   594	                }
   595	            }
   596	            Ok(_) => {}
   597	            Err(_) => break,
   598	        }
   599	    }
   600	    let _ = mdns.shutdown();
   601	
   602	    let mut servers: Vec<DiscoveredServer> = found.into_values().collect();
   603	    servers.sort_by(|a, b| a.name.cmp(&b.name));
   604	    Ok(servers)
   605	}
