    32	  if (!match) {
    33	    return remote;
    34	  }
    35	  const [, scheme, userinfo, rest] = match;
    36	  if (scheme.toLowerCase() === "ssh://" && userinfo.toLowerCase().startsWith("pair-")) {
    37	    const token = userinfo.slice("pair-".length);
    38	    return `${scheme}pair-<token:${token.slice(-6)}>@${rest}`;
    39	  }
    40	  return `${scheme}${userinfo.includes(":") ? "<credentials>" : userinfo}@${rest}`;
    41	};
