278	        &mut self,
279	        _channel: Channel<Msg>,
280	        reply: ChannelOpenHandle,
281	        _session: &mut Session,
282	    ) -> Result<(), Self::Error> {
283	        reply.accept().await;
284	        Ok(())
285	    }
286	
287	    async fn exec_request(
288	        &mut self,
289	        channel: ChannelId,
290	        data: &[u8],
291	        session: &mut Session,
292	    ) -> Result<(), Self::Error> {
293	        let raw = String::from_utf8_lossy(data).to_string();
294	        let Some((service, requested_path)) = parse_git_command(&raw) else {
295	            session.channel_failure(channel)?;
296	            return Ok(());
297	        };
298	        if !path_matches(
299	            &requested_path,
300	            &self.shared.served_name,
301	            &self.shared.repo_path,
302	        ) {
303	            session.channel_success(channel)?;
304	            fail_channel(session, channel, "Repository not found on this computer.");
305	            return Ok(());
306	        }
307	
308	        eprintln!("[local-sync] serving {service} for '{requested_path}'");
309	        // Serve the latest notes: the desktop edits its working tree without
310	        // committing, so pending changes are committed here — right before a
311	        // fetch reads history, and before a push so updateInstead never meets
312	        // a dirty tree. The dirty check matters: committing unconditionally
313	        // would add an empty commit per serve and reject phone pushes as
314	        // non-fast-forward.
315	        if let Ok(repo) = git2::Repository::open(&self.shared.repo_path) {
316	            if crate::git_has_changes(&repo) {
317	                let _ = crate::commit_all_changes(&repo, "Sync notes", &self.shared.branch);
318	            }
319	        }
320	
321	        let spawned = Command::new(&self.shared.git_path)
322	            .arg(service)
323	            .arg(&self.shared.repo_path)
324	            .stdin(Stdio::piped())
325	            .stdout(Stdio::piped())
326	            .stderr(Stdio::piped())
327	            .kill_on_drop(true)
328	            .spawn();
329	        let mut child = match spawned {
330	            Ok(child) => child,
331	            Err(error) => {
332	                session.channel_success(channel)?;
333	                fail_channel(session, channel, &format!("Failed to run git: {error}"));
334	                return Ok(());
335	            }
336	        };
337	
338	        session.channel_success(channel)?;
339	        if let Some(stdin) = child.stdin.take() {
340	            self.stdins.insert(channel, stdin);
341	        }
342	        pump_child_io(session, channel, child, service);
343	        Ok(())
344	    }
345	
346	    async fn data(
347	        &mut self,
348	        channel: ChannelId,
349	        data: &[u8],
350	        _session: &mut Session,
351	    ) -> Result<(), Self::Error> {
352	        if let Some(stdin) = self.stdins.get_mut(&channel) {
353	            if stdin.write_all(data).await.is_err() {
354	                self.stdins.remove(&channel);
355	            }
356	        }
357	        Ok(())
358	    }
359	
360	    async fn channel_eof(
361	        &mut self,
362	        channel: ChannelId,
363	        _session: &mut Session,
364	    ) -> Result<(), Self::Error> {
365	        // Dropping the pipe closes the child's stdin so git can finish.
366	        self.stdins.remove(&channel);
367	        Ok(())
368	    }
369	
370	    async fn channel_close(
371	        &mut self,
372	        channel: ChannelId,
373	        _session: &mut Session,
374	    ) -> Result<(), Self::Error> {
375	        self.stdins.remove(&channel);
376	        Ok(())
377	    }
378	}
