380	/// Forward the git child's stdout/stderr to the SSH channel, then report its
381	/// exit status and close the channel. A completed receive-pack changed the
382	/// live working tree, so the desktop UI is notified to refresh.
383	fn pump_child_io(session: &mut Session, channel: ChannelId, mut child: Child, service: &'static str) {
384	    let handle = session.handle();
385	    tokio::spawn(async move {
386	        let stdout = child.stdout.take();
387	        let stderr = child.stderr.take();
388	
389	        let out_handle = handle.clone();
390	        let out_task = async move {
391	            let Some(mut stdout) = stdout else { return };
392	            let mut buf = vec![0u8; 32 * 1024];
393	            loop {
394	                match stdout.read(&mut buf).await {
395	                    Ok(0) | Err(_) => break,
396	                    Ok(n) => {
397	                        if out_handle
398	                            .data(channel, Vec::from(&buf[..n]))
399	                            .await
400	                            .is_err()
401	                        {
402	                            break;
403	                        }
404	                    }
405	                }
406	            }
407	        };
408	        let err_handle = handle.clone();
409	        let err_task = async move {
410	            let Some(mut stderr) = stderr else { return };
411	            let mut buf = vec![0u8; 8 * 1024];
412	            loop {
413	                match stderr.read(&mut buf).await {
414	                    Ok(0) | Err(_) => break,
415	                    Ok(n) => {
416	                        if err_handle
417	                            .extended_data(channel, 1, Vec::from(&buf[..n]))
418	                            .await
419	                            .is_err()
420	                        {
421	                            break;
422	                        }
423	                    }
424	                }
425	            }
426	        };
427	        tokio::join!(out_task, err_task);
428	
429	        let code = child
430	            .wait()
431	            .await
432	            .ok()
433	            .and_then(|status| status.code())
434	            .unwrap_or(1) as u32;
435	        eprintln!("[local-sync] git process finished with exit code {code}");
436	        let _ = handle.exit_status_request(channel, code).await;
437	        let _ = handle.eof(channel).await;
438	        let _ = handle.close(channel).await;
439	        if service == "receive-pack" && code == 0 {
440	            eprintln!("[local-sync] push received — notifying the app to refresh notes");
441	            super::notify_local_sync_push_received();
442	        }
443	    });
444	}
