446	/// Send a git-visible error message and close the channel with exit status 128.
447	fn fail_channel(session: &mut Session, channel: ChannelId, message: &str) {
448	    let handle = session.handle();
449	    let message = format!("{message}\n");
450	    tokio::spawn(async move {
451	        let _ = handle.extended_data(channel, 1, message.into_bytes()).await;
452	        let _ = handle.exit_status_request(channel, 128).await;
453	        let _ = handle.eof(channel).await;
454	        let _ = handle.close(channel).await;
455	    });
456	}
