458	/// Parse a git exec command line: `git-upload-pack '/notes'` (also the spaced
459	/// `git upload-pack` spelling). Returns the git subcommand + the quoted path.
460	pub(super) fn parse_git_command(raw: &str) -> Option<(&'static str, String)> {
461	    let trimmed = raw.trim();
462	    let (service, rest) = if let Some(rest) = trimmed
463	        .strip_prefix("git-upload-pack")
464	        .or_else(|| trimmed.strip_prefix("git upload-pack"))
465	    {
466	        ("upload-pack", rest)
467	    } else if let Some(rest) = trimmed
468	        .strip_prefix("git-receive-pack")
469	        .or_else(|| trimmed.strip_prefix("git receive-pack"))
470	    {
471	        ("receive-pack", rest)
472	    } else {
473	        return None;
474	    };
475	    let path = rest.trim().trim_matches('\'').trim_matches('"').to_string();
476	    if path.is_empty() {
477	        return None;
478	    }
479	    Some((service, path))
480	}
