482	/// Minimal %XX decoding for URL paths (folder names with spaces etc.).
483	pub(super) fn percent_decode(value: &str) -> String {
484	    let bytes = value.as_bytes();
485	    let mut out = Vec::with_capacity(bytes.len());
486	    let mut i = 0;
487	    while i < bytes.len() {
488	        if bytes[i] == b'%' && i + 2 < bytes.len() {
489	            let hex = &value[i + 1..i + 3];
490	            if let Ok(byte) = u8::from_str_radix(hex, 16) {
491	                out.push(byte);
492	                i += 3;
493	                continue;
494	            }
495	        }
496	        out.push(bytes[i]);
497	        i += 1;
498	    }
499	    String::from_utf8_lossy(&out).to_string()
500	}
