502	/// Does the path a client asked for refer to the served notes repository?
503	pub(super) fn path_matches(
504	    requested: &str,
505	    served_name: &str,
506	    repo_path: &std::path::Path,
507	) -> bool {
508	    let stripped = requested.trim_start_matches('/').trim_end_matches('/');
509	    let decoded = percent_decode(stripped);
510	    if stripped == served_name || decoded == served_name {
511	        return true;
512	    }
513	    let full = percent_decode(requested.trim_end_matches('/'));
514	    full == repo_path.to_string_lossy()
515	}
