import type {
  NotesListMode,
  ProfileSyncSettings,
  ThemeMode,
} from "@typenotes/shared/types";
import {
  PROFILE_SYNC_STORAGE_KEY,
  DEFAULT_EDITOR_FONT_SIZE,
} from "../constants";

export const DEFAULT_PROFILE_SYNC_SETTINGS: ProfileSyncSettings = {
  gitRemoteUrl: "",
  gitBranch: "main",
  gitUsername: "",
  gitPassword: "",
  gitCommitMessage: "Sync notes",
  lastSuccessfulSyncAt: "",
  noteFileNameFormat: "utc_timestamp_slug",
  assemblyAiApiKey: "",
  mobileAutoTranscriptionEnabled: true,
  whisperModel: "large-v3",
  handwritingOcrProvider: "openai",
  openAiApiKey: "",
  openAiModel: "gpt-4.1-mini",
  huggingFaceApiKey: "",
  huggingFaceModel: "microsoft/trocr-base-handwritten",
  mobileAutoHandwritingOcrEnabled: true,
};

export const getInitialTheme = (): ThemeMode => {
  if (typeof window === "undefined") {
    return "dark";
  }
  const stored = window.localStorage.getItem("notes-viewer-theme");
  if (stored === "dark" || stored === "light") {
    return stored;
  }
  return "dark";
};

export const getInitialNotesListMode = (): NotesListMode => {
  if (typeof window === "undefined") {
    return "separate";
  }
  const stored = window.localStorage.getItem("notes-viewer-notes-list-mode");
  if (stored === "nested" || stored === "separate") {
    return stored;
  }
  return "separate";
};

export const getInitialHideArchivedFeedNotes = (): boolean => {
  if (typeof window === "undefined") {
    return true;
  }
  const stored = window.localStorage.getItem("notes-viewer-hide-archived-feed-notes");
  if (stored === "true") {
    return true;
  }
  if (stored === "false") {
    return false;
  }
  return true;
};

export const getStoredSyncValue = (key: string, fallback: string) => {
  if (typeof window === "undefined") {
    return fallback;
  }
  const stored = window.localStorage.getItem(key);
  return stored && stored.trim().length > 0 ? stored : fallback;
};

export const getStoredBooleanValue = (key: string, fallback: boolean) => {
  if (typeof window === "undefined") {
    return fallback;
  }
  const stored = window.localStorage.getItem(key);
  if (stored === "true") {
    return true;
  }
  if (stored === "false") {
    return false;
  }
  return fallback;
};

const normalizeHandwritingProvider = (
  value: string
): ProfileSyncSettings["handwritingOcrProvider"] =>
  value === "huggingface" ? "huggingface" : "openai";

const normalizeNoteFileNameFormat = (
  value: unknown
): ProfileSyncSettings["noteFileNameFormat"] => {
  if (value === "uuid_v7" || value === "uuid_v7_prefix_slug") {
    return value;
  }
  return "utc_timestamp_slug";
};

export const readProfileSyncStore = (): Record<string, Partial<ProfileSyncSettings>> => {
  if (typeof window === "undefined") {
    return {};
  }
  try {
    const raw = window.localStorage.getItem(PROFILE_SYNC_STORAGE_KEY);
    if (!raw) {
      return {};
    }
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === "object") {
      return parsed as Record<string, Partial<ProfileSyncSettings>>;
    }
  } catch {
    return {};
  }
  return {};
};

export const writeProfileSyncStore = (store: Record<string, Partial<ProfileSyncSettings>>) => {
  if (typeof window === "undefined") {
    return;
  }
  window.localStorage.setItem(PROFILE_SYNC_STORAGE_KEY, JSON.stringify(store));
};

export const removeProfileSyncSettings = (profileId: string) => {
  const id = profileId.trim();
  if (!id) {
    return;
  }
  const store = readProfileSyncStore();
  if (!(id in store)) {
    return;
  }
  delete store[id];
  writeProfileSyncStore(store);
};

export const getProfileSyncSettings = (profileId: string): ProfileSyncSettings => {
  const store = readProfileSyncStore();
  const stored = store[profileId] ?? {};
  const legacyFallback =
    profileId === "default"
      ? {
          gitRemoteUrl: getStoredSyncValue("notes-viewer-git-remote", ""),
          gitBranch: getStoredSyncValue("notes-viewer-git-branch", "main"),
          gitUsername: getStoredSyncValue("notes-viewer-git-username", ""),
          gitPassword: getStoredSyncValue("notes-viewer-git-password", ""),
          gitCommitMessage: getStoredSyncValue("notes-viewer-git-commit-message", "Sync notes"),
          lastSuccessfulSyncAt: getStoredSyncValue("notes-viewer-git-last-sync-at", ""),
          noteFileNameFormat: normalizeNoteFileNameFormat(
            getStoredSyncValue(
              "notes-viewer-note-file-name-format",
              DEFAULT_PROFILE_SYNC_SETTINGS.noteFileNameFormat
            )
          ),
          assemblyAiApiKey: getStoredSyncValue("notes-viewer-assemblyai-api-key", ""),
          mobileAutoTranscriptionEnabled: getStoredBooleanValue(
            "notes-viewer-mobile-auto-transcription-enabled",
            DEFAULT_PROFILE_SYNC_SETTINGS.mobileAutoTranscriptionEnabled
          ),
          handwritingOcrProvider: normalizeHandwritingProvider(
            getStoredSyncValue(
              "notes-viewer-handwriting-ocr-provider",
              DEFAULT_PROFILE_SYNC_SETTINGS.handwritingOcrProvider
            )
          ),
          openAiApiKey: getStoredSyncValue("notes-viewer-openai-api-key", ""),
          openAiModel: getStoredSyncValue(
            "notes-viewer-openai-model",
            DEFAULT_PROFILE_SYNC_SETTINGS.openAiModel
          ),
          huggingFaceApiKey: getStoredSyncValue("notes-viewer-huggingface-api-key", ""),
          huggingFaceModel: getStoredSyncValue(
            "notes-viewer-huggingface-model",
            DEFAULT_PROFILE_SYNC_SETTINGS.huggingFaceModel
          ),
          mobileAutoHandwritingOcrEnabled: getStoredBooleanValue(
            "notes-viewer-mobile-auto-handwriting-ocr-enabled",
            DEFAULT_PROFILE_SYNC_SETTINGS.mobileAutoHandwritingOcrEnabled
          ),
        }
      : {};

  return {
    gitRemoteUrl: stored.gitRemoteUrl ?? legacyFallback.gitRemoteUrl ?? DEFAULT_PROFILE_SYNC_SETTINGS.gitRemoteUrl,
    gitBranch: stored.gitBranch ?? legacyFallback.gitBranch ?? DEFAULT_PROFILE_SYNC_SETTINGS.gitBranch,
    gitUsername: stored.gitUsername ?? legacyFallback.gitUsername ?? DEFAULT_PROFILE_SYNC_SETTINGS.gitUsername,
    gitPassword: stored.gitPassword ?? legacyFallback.gitPassword ?? DEFAULT_PROFILE_SYNC_SETTINGS.gitPassword,
    gitCommitMessage:
      stored.gitCommitMessage ??
      legacyFallback.gitCommitMessage ??
      DEFAULT_PROFILE_SYNC_SETTINGS.gitCommitMessage,
    lastSuccessfulSyncAt:
      stored.lastSuccessfulSyncAt ??
      legacyFallback.lastSuccessfulSyncAt ??
      DEFAULT_PROFILE_SYNC_SETTINGS.lastSuccessfulSyncAt,
    noteFileNameFormat: normalizeNoteFileNameFormat(
      stored.noteFileNameFormat ??
        legacyFallback.noteFileNameFormat ??
        DEFAULT_PROFILE_SYNC_SETTINGS.noteFileNameFormat
    ),
    assemblyAiApiKey:
      stored.assemblyAiApiKey ??
      legacyFallback.assemblyAiApiKey ??
      DEFAULT_PROFILE_SYNC_SETTINGS.assemblyAiApiKey,
    mobileAutoTranscriptionEnabled:
      stored.mobileAutoTranscriptionEnabled ??
      legacyFallback.mobileAutoTranscriptionEnabled ??
      DEFAULT_PROFILE_SYNC_SETTINGS.mobileAutoTranscriptionEnabled,
    whisperModel:
      stored.whisperModel ?? DEFAULT_PROFILE_SYNC_SETTINGS.whisperModel,
    handwritingOcrProvider: normalizeHandwritingProvider(
      stored.handwritingOcrProvider ??
        legacyFallback.handwritingOcrProvider ??
        DEFAULT_PROFILE_SYNC_SETTINGS.handwritingOcrProvider
    ),
    openAiApiKey:
      stored.openAiApiKey ??
      legacyFallback.openAiApiKey ??
      DEFAULT_PROFILE_SYNC_SETTINGS.openAiApiKey,
    openAiModel:
      stored.openAiModel ??
      legacyFallback.openAiModel ??
      DEFAULT_PROFILE_SYNC_SETTINGS.openAiModel,
    huggingFaceApiKey:
      stored.huggingFaceApiKey ??
      legacyFallback.huggingFaceApiKey ??
      DEFAULT_PROFILE_SYNC_SETTINGS.huggingFaceApiKey,
    huggingFaceModel:
      stored.huggingFaceModel ??
      legacyFallback.huggingFaceModel ??
      DEFAULT_PROFILE_SYNC_SETTINGS.huggingFaceModel,
    mobileAutoHandwritingOcrEnabled:
      stored.mobileAutoHandwritingOcrEnabled ??
      legacyFallback.mobileAutoHandwritingOcrEnabled ??
      DEFAULT_PROFILE_SYNC_SETTINGS.mobileAutoHandwritingOcrEnabled,
  };
};

export const getInitialEditorFontSize = (): number => {
  if (typeof window === "undefined") {
    return DEFAULT_EDITOR_FONT_SIZE;
  }
  const stored = window.localStorage.getItem("notes-viewer-editor-font-size");
  if (stored) {
    const parsed = Number(stored);
    if (!Number.isNaN(parsed) && parsed >= 12 && parsed <= 28) {
      return parsed;
    }
  }
  return DEFAULT_EDITOR_FONT_SIZE;
};

// Persisted note-preview snapshots (one localStorage key per profile). Shared so
// the security feature can purge plaintext previews when encryption is enabled.
export const NOTE_PREVIEW_CACHE_PREFIX = "notes-viewer-note-previews-v1:";

export const clearPersistedNotePreviews = () => {
  if (typeof window === "undefined") {
    return;
  }
  for (let index = window.localStorage.length - 1; index >= 0; index -= 1) {
    const key = window.localStorage.key(index);
    if (key?.startsWith(NOTE_PREVIEW_CACHE_PREFIX)) {
      window.localStorage.removeItem(key);
    }
  }
};

import { useRef, type ReactNode } from "react";
import { useShallow } from "zustand/react/shallow";

import { AppearanceProvider } from "@/app/state/appearance-store";
import { SelectionProvider, useSelection } from "@/app/state/selection-store";
import { EditorProvider, useEditor } from "@/features/notes/editor/hooks/editor-context";
import { HandwritingProvider } from "@/features/handwriting/hooks/handwriting-context";
import { NotesTreeProvider, useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { ProfilesProvider } from "@/features/profiles/hooks/profiles-context";
import { RecordingsProvider } from "@/features/recording/hooks/recordings-context";
import { SecurityProvider } from "@/features/security/hooks/security-context";
import { GitSyncProvider } from "@/features/sync/hooks/git-sync-context";
import { useBackgroundSave } from "./lifecycle/use-background-save";
import { AppReadinessGate, AppSecurityGate } from "./readiness";

function FlushSaveBridge({
  flushSaveRef,
}: {
  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
}) {
  const { flushSave } = useEditor();
  flushSaveRef.current = flushSave;
  return null;
}

function AppLifecycle() {
  const { flushSave } = useEditor();
  useBackgroundSave(flushSave);
  return null;
}

function CaptureFeatureProviders({ children }: { children: ReactNode }) {
  const notesTree = useNotesTree();
  const selection = useSelection(
    useShallow((state) => ({
      activeFolder: state.activeFolder,
      setSelectedFolders: state.setSelectedFolders,
      setLastSelectedFolder: state.setLastSelectedFolder,
      setActiveFolder: state.setActiveFolder,
      setSelectedNotes: state.setSelectedNotes,
      setLastSelectedNote: state.setLastSelectedNote,
      setActiveNote: state.setActiveNote,
    }))
  );
  const editor = useEditor();

  const handleCapturedNoteComplete = async (result: {
    folder_path: string;
    note_path: string;
  }) => {
    await notesTree.refreshTree();
    selection.setSelectedFolders(new Set([result.folder_path]));
    selection.setLastSelectedFolder(result.folder_path);
    selection.setActiveFolder(result.folder_path);
    selection.setSelectedNotes(new Set([result.note_path]));
    selection.setLastSelectedNote(result.note_path);
    selection.setActiveNote(result.note_path);
    editor.clearDraft();
  };

  return (
    <RecordingsProvider
      activeFolder={selection.activeFolder}
      onRecordingComplete={handleCapturedNoteComplete}
    >
      <HandwritingProvider
        activeFolder={selection.activeFolder}
        onHandwritingComplete={handleCapturedNoteComplete}
      >
        {children}
      </HandwritingProvider>
    </RecordingsProvider>
  );
}

function UnlockedAppProviders({
  children,
  flushSaveRef,
}: {
  children: ReactNode;
  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
}) {
  return (
    <ProfilesProvider flushSaveRef={flushSaveRef}>
      <GitSyncProvider>
        <SelectionProvider>
          <EditorProvider>
            <NotesTreeProvider>
              <FlushSaveBridge flushSaveRef={flushSaveRef} />
              <AppLifecycle />
              <AppReadinessGate>
                <CaptureFeatureProviders>{children}</CaptureFeatureProviders>
              </AppReadinessGate>
            </NotesTreeProvider>
          </EditorProvider>
        </SelectionProvider>
      </GitSyncProvider>
    </ProfilesProvider>
  );
}

export function AppProviders({ children }: { children: ReactNode }) {
  const flushSaveRef = useRef<(() => Promise<void>) | null>(null);

  return (
    <AppearanceProvider>
      <SecurityProvider>
        <AppSecurityGate>
          <UnlockedAppProviders flushSaveRef={flushSaveRef}>
            {children}
          </UnlockedAppProviders>
        </AppSecurityGate>
      </SecurityProvider>
    </AppearanceProvider>
  );
}
import {
  createContext,
  useContext,
  useEffect,
  useState,
  useMemo,
  type ReactNode,
} from "react";
import type {
  AppConfig,
  NotesProfileSnapshot,
  ProfileSettings,
  ProfileSyncSettings,
} from "@typenotes/shared/types";
import { profileSyncSettingsFromState } from "@/features/profiles/lib/profile-sync-settings";
import { getErrorMessage } from "@typenotes/shared/errors";
import { useLegacyProfileSyncMigration } from "./use-legacy-profile-sync-migration";
import { useProfileActions } from "./use-profile-actions";

type ProfilesContextValue = {
  profilesSnapshot: NotesProfileSnapshot | null;
  profilesBusy: boolean;
  profilesError: string | null;
  profiles: NotesProfileSnapshot["profiles"];
  activeProfileId: string | null;
  activeProfileNotesRoot: string | null;
  appConfig: AppConfig | null;
  activeProfileSettings: ProfileSettings | null;
  syncSettings: ProfileSyncSettings;
  updateAppConfig: (patch: Partial<AppConfig>) => Promise<void>;
  updateActiveProfileSettings: (patch: Partial<ProfileSettings>) => Promise<void>;
  updateSyncSettings: (patch: Partial<ProfileSyncSettings>) => Promise<void>;
  refreshProfiles: () => Promise<NotesProfileSnapshot>;
  switchProfile: (profileId: string) => Promise<void>;
  createProfile: (input?: { name?: string; description?: string }) => Promise<void>;
  updateProfile: (
    profileId: string,
    patch: { name?: string; description?: string }
  ) => Promise<void>;
  deleteProfile: (profileId: string) => Promise<void>;
  setProfileNotesRoot: (profileId: string, notesRoot: string) => Promise<void>;
  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
};

const ProfilesContext = createContext<ProfilesContextValue | null>(null);

export function ProfilesProvider({
  children,
  flushSaveRef,
}: {
  children: ReactNode;
  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
}) {
  const [profilesSnapshot, setProfilesSnapshot] = useState<NotesProfileSnapshot | null>(null);
  const [profilesBusy, setProfilesBusy] = useState(false);
  const [profilesError, setProfilesError] = useState<string | null>(null);

  const profiles = profilesSnapshot?.profiles ?? [];
  const activeProfileId = profilesSnapshot?.activeProfileId ?? null;
  const activeProfile = useMemo(
    () => profiles.find((p) => p.id === activeProfileId) ?? null,
    [profiles, activeProfileId]
  );
  const activeProfileNotesRoot = activeProfile?.notes_root ?? null;
  const activeProfileSettings = activeProfile?.settings ?? null;
  const appConfig = profilesSnapshot?.appConfig ?? null;

  // The UI still consumes one settings object; the helper documents which
  // fields are app-wide and which belong to the active profile.
  const syncSettings = useMemo((): ProfileSyncSettings => {
    return profileSyncSettingsFromState(appConfig, activeProfileSettings);
  }, [appConfig, activeProfileSettings]);
  const {
    refreshProfiles,
    updateAppConfig,
    updateActiveProfileSettings,
    updateSyncSettings,
    switchProfile,
    createProfile,
    updateProfile,
    deleteProfile,
    setProfileNotesRoot,
  } = useProfileActions({
    appConfig,
    activeProfileId,
    activeProfileSettings,
    profiles,
    flushSaveRef,
    setProfilesSnapshot,
    setProfilesBusy,
    setProfilesError,
  });

  useLegacyProfileSyncMigration({
    profilesSnapshot,
    profilesBusy,
    activeProfileId,
    profiles,
    refreshProfiles,
    setProfilesBusy,
  });

  // Initial fetch
  useEffect(() => {
    void (async () => {
      setProfilesBusy(true);
      try {
        await refreshProfiles();
        setProfilesError(null);
      } catch (error) {
        const message = getErrorMessage(error);
        setProfilesError(message);
      } finally {
        setProfilesBusy(false);
      }
    })();
  }, [refreshProfiles]);

  return (
    <ProfilesContext.Provider
      value={{
        profilesSnapshot,
        profilesBusy,
        profilesError,
        profiles,
        activeProfileId,
