229	pub fn local_sync_server_status(app: &AppEnv) -> Result<LocalSyncServerStatus, String> {
230	    let repo_path = ensured_notes_root(app)?.to_string_lossy().to_string();
231	
232	    #[cfg(not(desktop))]
233	    {
234	        Ok(unsupported_status(repo_path))
235	    }
236	
237	    #[cfg(desktop)]
238	    {
239	        let guard = DAEMON
240	            .lock()
241	            .map_err(|_| "local sync server state is poisoned".to_string())?;
242	        let git_available = locate_git().is_some();
243	        let idle_timeout_minutes = configured_idle_timeout_minutes(app);
244	        Ok(match guard.as_ref() {
245	            Some(daemon) => running_status(daemon),
246	            None => idle_status(git_available, repo_path, idle_timeout_minutes),
247	        })
248	    }
