261	fn start_local_sync_server_with_access(
262	    app: &AppEnv,
263	    open_immediately: bool,
264	) -> Result<LocalSyncServerStatus, String> {
265	    #[cfg(not(desktop))]
266	    {
267	        let _ = app;
268	        Err(NOT_SUPPORTED_MSG.to_string())
269	    }
270	
271	    #[cfg(desktop)]
272	    {
273	        let root = ensured_notes_root(app)?;
274	        let git = locate_git().ok_or_else(|| GIT_MISSING_MSG.to_string())?;
275	        eprintln!("[local-sync] start requested: repo='{}'", root.display());
276	
277	        let mut guard = DAEMON
278	            .lock()
279	            .map_err(|_| "local sync server state is poisoned".to_string())?;
280	
281	        // Already running? Return current status (idempotent).
282	        if let Some(daemon) = guard.as_ref() {
283	            if open_immediately {
284	                daemon.access.open_window();
285	            }
286	            eprintln!(
287	                "[local-sync] start skipped: server already running for repo='{}' branch='{}'",
288	                daemon.repo_path.display(),
289	                daemon.branch
290	            );
291	            return Ok(running_status(daemon));
292	        }
293	
294	        // Make sure the notes folder is a repo and will accept pushes to its
295	        // checked-out branch by updating the working tree. Pending desktop
296	        // edits are committed by the server just before it serves each fetch
297	        // or push (see ssh_server), so starting — including the settings
298	        // page's auto-start — never creates commits by itself.
299	        let repo = ensure_git_repo(&root)?;
300	        repo.config()
301	            .and_then(|mut cfg| cfg.set_str("receive.denyCurrentBranch", "updateInstead"))
302	            .map_err(|e| format!("Failed to configure repo for local sync: {e}"))?;
303	        let branch = resolve_target_branch(&repo, None);
304	        switch_or_prepare_branch(&repo, &branch)?;
305	        drop(repo);
306	
307	        let served_name = root
308	            .file_name()
309	            .and_then(|name| name.to_str())
310	            .ok_or_else(|| "Notes folder name is not valid UTF-8.".to_string())?
311	            .to_string();
312	
313	        let (host_key, host_key_sha256) = devices::ensure_host_key(app)?;
314	        let (token_path, token) = devices::load_or_create_pairing_token(app)?;
315	        let pairing_token = Arc::new(Mutex::new(token));
316	        let consumed_pairing_tokens = Arc::new(Mutex::new(Vec::new()));
317	        let devices_path = devices::devices_path(app)?;
318	        let idle_timeout = Duration::from_secs(configured_idle_timeout_minutes(app) * 60);
319	        let access = Arc::new(ssh_server::SyncAccessState::new(
320	            idle_timeout,
321	            open_immediately,
322	        ));
323	        let shared = Arc::new(ssh_server::ServerShared {
324	            git_path: git,
325	            repo_path: root.clone(),
326	            served_name: served_name.clone(),
327	            branch: branch.clone(),
328	            pairing_token: pairing_token.clone(),
329	            consumed_pairing_tokens,
330	            pairing_token_path: token_path,
331	            devices_path: devices_path.clone(),
332	            access: access.clone(),
333	        });
334	        let server = ssh_server::start_ssh_server(shared, &host_key, LOCAL_SYNC_PORT)?;
335	
336	        // Advertise over mDNS so phones can auto-discover this server without
337	        // typing or scanning anything. Best-effort: failure never blocks hosting.
338	        // The advertised URL deliberately omits the pairing token: mDNS is
339	        // plaintext broadcast, and the token must stay QR-only (already-paired
340	        // devices authenticate by key under any username).
341	        let host = detect_lan_ip();
342	        let mdns = host.as_ref().and_then(|ip| {
343	            let ssh_url = ssh_public_url(ip, &served_name);
344	            advertise_mdns(
345	                ip,
346	                &served_name,
347	                &branch,
348	                &ssh_url,
349	                &host_key_sha256,
350	            )
351	        });
352	
353	        let daemon = RunningDaemon {
354	            server,
355	            host,
356	            served_name,
357	            branch,
358	            repo_path: root,
359	            pairing_token,
360	            devices_path,
361	            host_key_sha256,
362	            access,
363	            mdns,
364	        };
365	        let status = running_status(&daemon);
366	        eprintln!(
367	            "[local-sync] server running: listen=0.0.0.0:{LOCAL_SYNC_PORT} advertised_host={} branch='{}' repo='{}' paired_devices={}",
368	            daemon.host.as_deref().unwrap_or("<unknown>"),
369	            daemon.branch,
370	            daemon.repo_path.display(),
371	            status.paired_devices.len()
372	        );
373	        *guard = Some(daemon);
374	        Ok(status)
375	    }
376	}
