import { describe, expect, it, vi } from "vitest";

import {
  classifyDesktopApprovalError,
  runWithDesktopApproval,
} from "./sync-approval";

describe("desktop sync approval", () => {
  it("classifies stable server markers", () => {
    expect(
      classifyDesktopApprovalError(
        new Error("remote: TYPE_SYNC_APPROVAL_REQUIRED: Waiting for approval")
      )
    ).toBe("required");
    expect(
      classifyDesktopApprovalError(new Error("TYPE_SYNC_APPROVAL_DECLINED: no"))
    ).toBe("declined");
    expect(classifyDesktopApprovalError(new Error("connection refused"))).toBeNull();
  });

  it("waits and retries until the desktop opens the window", async () => {
    const waiting = vi.fn();
    const sleep = vi.fn(async () => {});
    let attempts = 0;
    const result = await runWithDesktopApproval(
      async () => {
        attempts += 1;
        if (attempts === 1) {
          throw new Error("TYPE_SYNC_APPROVAL_REQUIRED");
        }
        return "synced";
      },
      { onWaiting: waiting, sleep }
    );

    expect(result).toBe("synced");
    expect(attempts).toBe(2);
    expect(waiting).toHaveBeenCalledOnce();
    expect(sleep).toHaveBeenCalledWith(1500);
  });

  it("stops retrying when the desktop declines", async () => {
    await expect(
      runWithDesktopApproval(
        async () => {
          throw new Error("TYPE_SYNC_APPROVAL_DECLINED");
        },
        { onWaiting: () => {}, sleep: async () => {} }
      )
    ).rejects.toThrow("declined on the desktop");
  });
});

import { getErrorMessage } from "@typenotes/shared/errors";

const APPROVAL_REQUIRED_MARKER = "type_sync_approval_required";
const APPROVAL_DECLINED_MARKER = "type_sync_approval_declined";

export type DesktopApprovalRetryOptions = {
  onWaiting: () => void;
  timeoutMs?: number;
  retryMs?: number;
  now?: () => number;
  sleep?: (milliseconds: number) => Promise<void>;
};

export const classifyDesktopApprovalError = (
  error: unknown
): "required" | "declined" | null => {
  const message = getErrorMessage(error).toLowerCase();
  if (message.includes(APPROVAL_REQUIRED_MARKER)) {
    return "required";
  }
  if (message.includes(APPROVAL_DECLINED_MARKER)) {
    return "declined";
  }
  return null;
};

export const runWithDesktopApproval = async <T>(
  work: () => Promise<T>,
  options: DesktopApprovalRetryOptions
): Promise<T> => {
  const now = options.now ?? Date.now;
  const sleep =
    options.sleep ??
    ((milliseconds: number) =>
      new Promise<void>((resolve) => setTimeout(resolve, milliseconds)));
  const deadline = now() + (options.timeoutMs ?? 2 * 60 * 1000);

  while (true) {
    try {
      return await work();
    } catch (error) {
      const approval = classifyDesktopApprovalError(error);
      if (approval === "declined") {
        throw new Error("The sync request was declined on the desktop.");
      }
      if (approval !== "required") {
        throw error;
      }
      if (now() >= deadline) {
        throw new Error("The desktop did not approve the sync request in time.");
      }
      options.onWaiting();
      await sleep(options.retryMs ?? 1500);
    }
  }
};

